const u = $json || {};
const m = u.message || u.edited_message || {};

const text = String(m.text || m.caption || '').trim();

const chatId = m.chat?.id != null ? String(m.chat.id) : null;
const userId = m.from?.id != null ? String(m.from.id) : null;
const messageId = m.message_id ?? null;

// ---------------------------------------
// 1) Extract X / Twitter URL
// ---------------------------------------
const urlMatch = text.match(
  /https?:\/\/(?:www\.)?(?:x\.com|twitter\.com)\/(?:[A-Za-z0-9_]+|i\/web)\/status\/(\d+)(?:[^\s]*)?/i
);

let xUrl = null;
let tweetId = null;

if (urlMatch) {
  tweetId = urlMatch[1];

  try {
    const parsed = new URL(urlMatch[0]);

    // Canonical X URL without ?s=20 etc.
    xUrl = `https://x.com${parsed.pathname}`;
  } catch {
    xUrl = urlMatch[0].split('?')[0];
  }
}

// ---------------------------------------
// 2) Remove URL from text
// ---------------------------------------
let remaining = text
  .replace(/https?:\/\/\S+/ig, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// ---------------------------------------
// 3) Detect media type
// ---------------------------------------
let mediaType = 'goal';

if (
  /ملخص|ملخص\s*الأهداف|ملخص\s*الاهداف|جميع\s*الأهداف|جميع\s*الاهداف|highlights?|summary/i.test(remaining)
) {
  mediaType = 'highlights';
}

// Remove media words before team parsing
remaining = remaining
  .replace(/ملخص\s*الأهداف/ig, ' ')
  .replace(/ملخص\s*الاهداف/ig, ' ')
  .replace(/جميع\s*الأهداف/ig, ' ')
  .replace(/جميع\s*الاهداف/ig, ' ')
  .replace(/ملخص/ig, ' ')
  .replace(/highlights?/ig, ' ')
  .replace(/summary/ig, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// ---------------------------------------
// 4) Extract team names
// Current expected input:
// الهلال الشباب ملخص
//
// Also supports:
// الهلال | الشباب
// الهلال × الشباب
// الهلال ضد الشباب
// ---------------------------------------
let teamA = '';
let teamB = '';

const explicitParts = remaining
  .split(/\s*(?:\||×| ضد | vs\.? | VS\.?)\s*/)
  .map(v => v.trim())
  .filter(Boolean);

if (explicitParts.length >= 2) {
  teamA = explicitParts[0];
  teamB = explicitParts[1];
} else {
  const words = remaining
    .split(/\s+/)
    .map(v => v.trim())
    .filter(Boolean);

  // For now: first word = first team, second word = second team
  if (words.length >= 2) {
    teamA = words[0];
    teamB = words[1];
  }
}

// ---------------------------------------
// 5) Clean file-safe names
// ---------------------------------------
function cleanName(v) {
  return String(v || '')
    .trim()
    .replace(/[\\/:*?"<>|]+/g, '-')
    .replace(/\s+/g, ' ');
}

teamA = cleanName(teamA);
teamB = cleanName(teamB);

// ---------------------------------------
// 6) Detect attached Telegram video too
// ---------------------------------------
const video = m.video || null;
const document = m.document || null;

const isVideoDocument =
  !!document &&
  /^video\//i.test(String(document.mime_type || ''));

const telegramVideo = video || (isVideoDocument ? document : null);

let inputKind = 'invalid';

if (telegramVideo?.file_id) {
  inputKind = 'telegram_video';
} else if (xUrl) {
  inputKind = 'x_url';
}

// ---------------------------------------
// Final validation
// ---------------------------------------
const valid = Boolean(
  inputKind !== 'invalid' &&
  teamA &&
  teamB
);

return [
  {
    json: {
      valid,

      input_kind: inputKind,
      source: 'telegram',

      chat_id: chatId,
      user_id: userId,
      message_id: messageId,

      original_text: text,

      x_url: xUrl,
      tweet_id: tweetId,

      team_a: teamA,
      team_b: teamB,
      matchup_key: `${teamA}__${teamB}`,

      media_type: mediaType,

      telegram_file_id: telegramVideo?.file_id || null,
      telegram_file_unique_id:
        telegramVideo?.file_unique_id || null,

      telegram_mime_type:
        telegramVideo?.mime_type || 'video/mp4'
    }
  }
];

const src = $json || {};

function t(v){ return String(v ?? '').trim(); }
function safeName(v) {
  return t(v)
    .replace(/[\\/:*?"<>|]+/g, '-')
    .replace(/\s+/g, ' ')
    .slice(0, 90);
}

const teamA = safeName(src.team_a ?? src.home_team ?? src.team1 ?? src.first_team);
const teamB = safeName(src.team_b ?? src.away_team ?? src.team2 ?? src.second_team);

let mediaType = t(src.media_type || src.type || 'goal').toLowerCase();
if (['match_highlights','summary','highlight','highlights'].includes(mediaType)) mediaType = 'highlights';
else mediaType = 'goal';

const rawUrl = t(src.x_url ?? src.url ?? src.source_url ?? src.tweet_url);
const match = rawUrl.match(/https?:\/\/(?:www\.)?(?:x\.com|twitter\.com)\/(?:[A-Za-z0-9_]+|i\/web)\/status\/(\d+)(?:[^\s]*)?/i);

let xUrl = match ? match[0].replace(/[),.;]+$/g, '') : '';
const tweetId = match ? match[1] : null;

if (xUrl) {
  try {
    const u2 = new URL(xUrl);
    xUrl = `https://x.com${u2.pathname}`;
  } catch {}
}

return [{
  json: {
    source: 'automation',
    input_kind: 'x_url',
    valid: Boolean(teamA && teamB && xUrl && tweetId),

    chat_id: t(src.chat_id) || null,
    message_id: null,

    team_a: teamA,
    team_b: teamB,
    matchup_key: `${teamA}__${teamB}`,

    media_type: mediaType,

    x_url: xUrl,
    tweet_id: tweetId,

    telegram_file_id: null,
    telegram_file_unique_id: null,
    telegram_mime_type: null,
    telegram_file_name: null,

    original_text: t(src.original_text || src.caption || ''),

    automation_source: t(src.automation_source || src.source || 'media_search_automation'),

    drive_folder_id: t(src.drive_folder_id) || '1xZSyG1MHG63w-Q87ssAKWbFScLq4fBgl',
    fastsaver_api_key: t(src.fastsaver_api_key) || 'PUT_FASTSAVER_API_KEY_HERE',
    next_workflow_id: t(src.next_workflow_id) || 'PUT_MOTION_PRODUCER_WORKFLOW_ID_HERE'
  }
}];
